void reset_lvl(void)
{
    clear_draw_page(page3);
    image_color_depth = 8;
    drawpage = page3;
    ++tileid;
    if (tileid >= 0x29)
        tileid = 0;
    draw_background_tiles();
    copy_screen_span_entry(page3, 0, page2, 0, vga_state.buffer_size);
    if (image_buffer_error_code != 0)
        fatal_exit(image_buffer_error_code, 0);
}

void load_and_draw_level(void)
{
    int column;
    int row;

    image_color_depth = 8;
    drawpage = page2;
    cell_cursor = (unsigned short *)&brick_code_map;
    remaining_brick_count = 0;
    if (bonus_index != 0) {
        for (scratch = 0; scratch < 0x120; ++scratch) {
            *((unsigned char *)cell_cursor++ + 1) = 0;
        }
        enemy_spawn_wait_time = bonus_stage_enemy_intervals[bonus_index];
        remaining_brick_count = bricks[bonus_index];
    } else {
        level_data_cursor += level_number * 0x24a;
        f_13889(level_data_cursor, (int)&enemy_spawn_wait_time, 2);
        f_13889(level_data_cursor + 2, (int)spell_slots, 8);
        f_13889(level_data_cursor + 10, (int)&brick_code_map, 0x240);
        for (row = 0; row < 0x10; row++) {
            for (column = 0; column < 0x12; column++) {
                current_brick_code = ((unsigned char *)cell_cursor)[1];
                if (current_brick_code > 0xff) {
                    current_brick_code = 0xff;
                    ((unsigned char *)cell_cursor)[1] = (unsigned char)current_brick_code;
                }
                if (current_brick_code >= 1 && current_brick_code <= 0x90)
                    ++remaining_brick_count;
                if (current_brick_code >= 0xfa && current_brick_code <= 0x100) {
                    ((IndexBits *)cell_cursor)->value = brick_code_mapping[current_brick_code];
                }
                if (current_brick_code == 0xf8) {
                    portal_start_x = column * 16 + 16;
                    portal_y_source = row * 8 + 24;
                }
                if (current_brick_code == 0xf9) {
                    portal_exit_xpos = column * 16 + 16;
                    portal_destination_y = row * 8 + 24;
                }
                if (current_brick_code != 0) {
                    sprite_metadata = brick_art_start + *(int *)(brick_sprite_offsets_first + current_brick_code * 8);
                    draw_bob_sprite(sprite_metadata, column * 16 + 16, row * 8 + 24);
                }
                ++cell_cursor;
            }
        }
    }
}

int wait_level(void)
{
    int start_result;

    init_stage_palette();
    hook_flags_word = ((*(short *)&hook_flags_word) & 0xfffe) & 0xfffd;
    space_pressed = 0;
    set_image_pages((int)sprite_commands, 0x100, 4, (int)frnt_pg_upd_buf, (int)back_pg_upd_buf);
    while (1) {
        update_mouse();
        advance_tracks();
        queue_draws();
        redraw_image_region(0, 0);
        if (image_buffer_error_code) {
            fatal_exit(image_buffer_error_code, 0);
        }
        show_page();
        f_9d40(1);
        handle_s_key();
        if (space_pressed || (mouse_btn != mouse_btn_old && mouse_btn) || keyboard_scan_byte == 1 || tick >= 0x2e) break;
    }
    if (tick == 0x2e) {
        start_result = -1;
    } else {
        start_result = 0;
    }
    drawpage = page2;
    tick = 0x2e;
    advance_tracks();
    queue_draws();
    redraw_image_region(0, 0);
    copy_screen_span_entry(page2, 0, src_page, 0, vga_state.buffer_size);
    copy_screen_span_entry(page2, 0, dst_page, 0, vga_state.buffer_size);
    set_image_pages((int)sprite_commands, 0x100, 4, (int)frnt_pg_upd_buf, (int)back_pg_upd_buf);
    return start_result;
}

void init_stage_palette(void)
{
    set_pg();
    sprite_base = tile_art_base;
    transition_track_data = (unsigned char *)&level_palette_transition_tracks;
    path_count = 12;
    init_tracks();
    clear_draw_page(src_page);
    clear_draw_page(dst_page);
    write_vga_palette(palette_base);
}

void entry_prompt(void)
{
    set_pg();
    transition_track_data = (unsigned char *)&level_number_transition_tracks_a;
    write_level_number_glyphs();
    wait_input(0x78);
    if (tick == 0x78) {
        transition_track_data = (unsigned char *)&tracks;
        write_level_number_glyphs();
        if (image_buffer_error_code != 0)
            fatal_exit(image_buffer_error_code, 0);
        wait_input(0x32);
    }
    copy_screen_span_entry(page2, 0, src_page, 0, vga_state.buffer_size);
    copy_screen_span_entry(page2, 0, dst_page, 0, vga_state.buffer_size);
}

void write_level_number_glyphs(void)
{
    sprite_base = fill_sprite_data;
    path_count = 6;
    init_tracks();
    *(int *)(transition_track_data + 0x44) = level_digit_sprite_records[(((int)level_number + 1) / 10) % 10].value;
    *(int *)(transition_track_data + 0x74) = level_digit_sprite_records[((int)level_number + 1) % 10].value;
}

void redraw_level_state(void)
{
    stop_audio_stream();
    prep_level();
    copy_screen_span_entry(page2, 0, src_page, 0, vga_state.buffer_size);
    copy_screen_span_entry(page2, 0, dst_page, 0, vga_state.buffer_size);
    move_mouse_to(((int *)racket_object)[0], ((int *)racket_object)[1]);
}

void prepare_game_asset_read(void)
{
    sprite_base = fill_sprite_data;
    path_count = 4;
    set_pg();
    init_tracks();
}

void draw_status(void)
{
    configure_text_renderer((int)monster_font_glyph_metrics, monster_art, 0, 8, 8);
    set_text_clip_rect(vga_state.left, vga_state.top, vga_state.right, vga_state.bottom);
    drawpage = page2;
    racket_state[2] = -1;
    racket_state[6] = -1;
    draw_zero_padded_number(0x38, 4, racket_state[5], 10, 6);
    draw_zero_padded_number(0x99, 4, racket_state[1] / 0x71, 10, 2);
    draw_zero_padded_number(0x108, 4, *(int *)high_score_values, 10, 6);
    copy_screen_span_entry(page2, 0, src_page, 0, vga_state.buffer_size);
    copy_screen_span_entry(page2, 0, dst_page, 0, vga_state.buffer_size);
    drawpage = src_page;
}

void update_game_status_panel(void)
{
    unsigned char saved_video_page;
    int saved_palette_state;

    saved_video_page = (unsigned char)drawpage;
    saved_palette_state = image_color_depth;
    image_color_depth = 8;
    if (next_extra_life_score < racket_state[5]) {
        racket_state[1] += 0x71;
        next_extra_life_score += 0x7d0;
        submit_audio_request(0x3c);
    }

    if (racket_state[5] != racket_state[6] || racket_state[1] != racket_state[2]) {
        configure_text_renderer((int)monster_font_glyph_metrics, monster_art, 0, 8, 8);
    }
    set_text_clip_rect(vga_state.left, vga_state.top, vga_state.right, vga_state.bottom);

    if (racket_state[5] != racket_state[6]) {
        racket_state[6] = racket_state[5];
        drawpage = page2;
        draw_zero_padded_number(0x38, 4, racket_state[5], 10, 6);
        copy_clipped_screen_rectangle(page2, 0x38, 4, 0x66, 0xb, src_page, 0x38, 4);
        copy_clipped_screen_rectangle(page2, 0x38, 4, 0x66, 0xb, dst_page, 0x38, 4);
    }

    if (racket_state[1] != racket_state[2]) {
        racket_state[2] = racket_state[1];
        drawpage = page2;
        draw_zero_padded_number(0x99, 4, racket_state[1] / 0x71, 10, 2);
        copy_clipped_screen_rectangle(page2, 0x99, 4, 0xa6, 0xb, src_page, 0x99, 4);
        copy_clipped_screen_rectangle(page2, 0x99, 4, 0xa6, 0xb, dst_page, 0x99, 4);
    }

    drawpage = saved_video_page;
    image_color_depth = saved_palette_state;
}

void process_brick_hit(int column, int cell_index, int velocity_x, int velocity_y)
{
    unsigned char saved_video_page;
    int pixel_x;
    int pixel_y;

    saved_video_page = (unsigned char)drawpage;
    pixel_x = column * 16 + 16;
    pixel_y = cell_index / 18 * 8 + 24;
    racket_state[5] += 1 << *(int *)(racket_object + 0x24);
    drawpage = page2;
    copy_tile_to_page(pixel_x, pixel_y);
    drawpage = src_page;
    copy_tile_to_page(pixel_x, pixel_y);
    drawpage = dst_page;
    copy_tile_to_page(pixel_x, pixel_y);

    if (velocity_x == 0 && velocity_y == 0) {
        velocity_x = -1;
        velocity_y = -1;
        if ((frames & 8) != 0)
            velocity_x = -velocity_x;
    }

    spawn_animated_sprite(pixel_x, pixel_y, velocity_x, velocity_y, brick_art_start,
           (int)(brick_sprite_offsets_remaining + (current_brick_code - 1) * 8), 0x12);
    if (current_brick_code >= 0x31 && current_brick_code <= 0x60) {
        if (((struct Cell *)cell_cursor)[column].hi) {
            spawn_falling_spell(((struct Cell *)cell_cursor)[column].hi - 1, ((struct Cell *)cell_cursor)[column].lo, pixel_x + 8, pixel_y + 4);
        }
    }
    ((struct Cell *)cell_cursor)[column].flag = 0;
    if (current_brick_code >= 1 && current_brick_code <= 0x90)
        --remaining_brick_count;
    drawpage = saved_video_page;
}

void draw_level_tile_on_pages(int column, int row_offset, int tile_id)
{
    unsigned char saved_video_page;
    int pixel_x;
    int pixel_y;
    int saved_palette_state;

    saved_video_page = (unsigned char)drawpage;
    saved_palette_state = image_color_depth;
    image_color_depth = 8;
    pixel_x = column * 16 + 16;
    pixel_y = row_offset / 18 * 8 + 24;
    sprite_metadata = brick_art_start + *(int *)(brick_sprite_offsets_first + tile_id * 8);
    drawpage = page2;
    draw_bob_sprite(sprite_metadata, pixel_x, pixel_y);
    drawpage = src_page;
    draw_bob_sprite(sprite_metadata, pixel_x, pixel_y);
    drawpage = dst_page;
    draw_bob_sprite(sprite_metadata, pixel_x, pixel_y);
    image_color_depth = saved_palette_state;
    drawpage = saved_video_page;
}

void copy_tile_to_page(int pixel_x, int pixel_y)
{
    copy_clipped_screen_rectangle(page3, pixel_x, pixel_y, pixel_x + 15, pixel_y + 7, drawpage, pixel_x, pixel_y);
}

void refresh_video_pages(int a)
{
    short value;
    if (page_idx != src_page)
        value = src_page;
    else
        value = dst_page;
    drawpage = value;
    copy_screen_span_entry(page2, 0, drawpage, 0, vga_state.buffer_size);
    show_page();
    f_9d40(0);
    write_vga_palette(a);
    copy_screen_span_entry(page2, 0, src_page, 0, vga_state.buffer_size);
    copy_screen_span_entry(page2, 0, dst_page, 0, vga_state.buffer_size);
}
